from pathlib import Path
from collections import Counter
from hashlib import sha256
from html.parser import HTMLParser
from urllib.parse import urlsplit, unquote
import json

class Page(HTMLParser):
    def __init__(self, raw):
        super().__init__()
        self.links = Counter()
        self.sections = Counter()
        self.feed(raw.decode('utf-8'))
        self.close()

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'a' and attrs.get('href'):
            url = urlsplit(attrs['href'])
            if not url.scheme and not url.netloc and url.path:
                self.links[unquote(url.path)] += 1
        if attrs.get('id'):
            self.sections[attrs['id']] += 1

site = Path('products/sites/shopify-catalogue-example')
root = Path('products/distribution/catalogue-example-baseline-reconciliation')
paths = {
    'captured_live': Path('products/distribution/catalogue-editor-example-placement/live-baseline.html'),
    'checkout': site / 'index.html',
    'offline_preview': root / 'offline-preview/index-preview.html',
}
observations = {}
parsed = {}
for label, path in paths.items():
    raw = path.read_bytes()
    parsed[label] = Page(raw)
    observations[label] = {'path': str(path), 'sha256': sha256(raw).hexdigest(), 'bytes': len(raw)}
live = parsed['captured_live']
for label in ('checkout', 'offline_preview'):
    page = parsed[label]
    inventory = paths[label].parent if label == 'checkout' else site
    observations[label].update({
        'relative_link_additions': dict(page.links - live.links),
        'relative_link_removals': dict(live.links - page.links),
        'id_additions': dict(page.sections - live.sections),
        'id_removals': dict(live.sections - page.sections),
        'missing_relative_targets_in_checkout_or_preview': sorted(target for target in page.links if not (inventory / target.lstrip('/')).is_file() and not (paths[label].parent / target.lstrip('/')).is_file()),
    })
result = {'scope': 'Structural comparison against saved live bytes. Target presence is checked in selected repository inputs, and does not prove live availability or release eligibility.', 'pages': observations}
output = root / 'consolidation-link-inventory.json'
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
